body:
**Describe the bug**
We appear to be getting a incorrect cache hit when using criteria with loader options

**Expected behavior**
The query parameters should be updated.

**To Reproduce**

```py
from sqlalchemy import (
    Column, Integer, String, ForeignKey, create_engine
)

from sqlalchemy.ext.declarative import declarative_base

from sqlalchemy.orm import (
    relationship, backref, sessionmaker, selectinload
)
from sqlalchemy.ext.associationproxy import (
    association_proxy
)

Base = declarative_base()


class Entity(Base):
    __tablename__ = 'entity'

    id = Column(
        Integer, primary_key=True
    )


class Register(Base):
    __tablename__ = 'register'

    id = Column(
        Integer, primary_key=True
    )

    name = Column(
        String(64)
    )

    attribute_type = Column(
        String(64)
    )

    __mapper_args__ = {
        'polymorphic_on': attribute_type
    }


class ObjectRegister(Register):
    __mapper_args__ = {
        'polymorphic_identity': 'object_registry'
    }


class ObjectLink(Base):
    __tablename__ = 'object_link'

    id = Column(
        Integer, primary_key=True
    )

    entity_id = Column(
        Integer, ForeignKey(
            Entity.id
        )
    )

    entity = relationship(
        Entity, backref=backref(
            'links'
        )
    )

    object_register_id = Column(
        Integer, ForeignKey(ObjectRegister.id)
    )

    object_register = relationship(
        ObjectRegister
    )

    key = association_proxy(
        'object_register', 'name'
    )


engine = create_engine(
    'sqlite:///:memory:', echo=True
)

Base.metadata.create_all(engine)

Session = sessionmaker(
    bind=engine
)

session = Session()

session.add(
    Entity(
        id=1
    )
)
session.add(
    ObjectRegister(
        id=1, name='EXISTS'
    )
)

session.add(
    ObjectLink(entity_id=1, object_register_id=1)
)

session.commit()


def get_query(key_name):
    query = session.query(
        Entity
    )

    query = query.options(
        selectinload(
            Entity.links.and_(
                ObjectLink.key.in_(
                    [key_name]
                )
            )
        )
    )

    return query

# Correct
#
# 2021-03-26 10:28:12,299 INFO sqlalchemy.engine.Engine SELECT object_link.entity_id AS object_link_entity_id,
#   object_link.id AS object_link_id, object_link.object_register_id AS object_link_object_register_id
# FROM object_link
# WHERE object_link.entity_id IN (?) AND (EXISTS (SELECT 1
# FROM register
# WHERE register.id = object_link.object_register_id AND register.attribute_type IN (?) AND register.name IN (?)))
# 2021-03-26 10:28:12,300 INFO sqlalchemy.engine.Engine [generated in 0.00054s] (1, 'object_registry', 'EXISTS')
assert 1 == len(get_query('EXISTS').all()[0].links)

# Should not find any matching links but appears to run with the same query / params as before.
#
# 2021-03-26 10:28:12,303 INFO sqlalchemy.engine.Engine SELECT object_link.entity_id AS object_link_entity_id,
#   object_link.id AS object_link_id, object_link.object_register_id AS object_link_object_register_id
# FROM object_link
# WHERE object_link.entity_id IN (?) AND (EXISTS (SELECT 1
# FROM register
# WHERE register.id = object_link.object_register_id AND register.attribute_type IN (?) AND register.name IN (?)))
# 2021-03-26 10:28:12,303 INFO sqlalchemy.engine.Engine [cached since 0.004025s ago] (1, 'object_registry', 'EXISTS')
assert 0 == len(get_query('NONE_EXISTING').all()[0].links)


```


**Versions.**
 - OS: CentOS Linux release 8.2.2004 (Core) 
 - Python: Python 2.7.17
 - SQLAlchemy: 1.4.3
 - Database: mariadb / sqlite ( tested ) 
 - DBAPI: any

**Additional context**
There are other cases that I have not yet been able to reproduce outside of our main application where it looks like the criteria is fully skipped and not added to the query at all (  incorrect cache hit? ) as it works if sqlalchemy is reloaded.

**Cheers**
